    const hero = JSON.parse(getContent.get('hero')?.content || '{}');
    const about = JSON.parse(getContent.get('about')?.content || '{}');
    const offers = JSON.parse(getContent.get('offers')?.content || '{}');
    const booksSection = JSON.parse(getContent.get('books')?.content || '{}');
    const newsletter = JSON.parse(getContent.get('newsletter')?.content || '{}');
    const contact = JSON.parse(getContent.get('contact')?.content || '{}');
    const social = JSON.parse(getContent.get('social')?.content || '{}');

    // Get published books
    const books = db.prepare(`
        SELECT * FROM books 
        WHERE is_published = 1 
        ORDER BY created_at DESC
    `).all();

    // Get settings
    const getSetting = db.prepare('SELECT value FROM settings WHERE key = ?');
    const siteName = getSetting.get('site_name')?.value || 'JCROWN DIGITALS';
    const contactEmail = getSetting.get('contact_email')?.value || '';

    res.render('index', {
        title: siteName,
        hero,
        about,
        offers,
        booksSection,
        newsletter,
        contact,
        social,
        contactEmail,
        books,
        page: 'home'
    });
});

// Download free book
router.get('/download/:id', (req, res) => {
    const db = require('../db/database');
    const bookId = req.params.id;

    const book = db.prepare('SELECT * FROM books WHERE id = ? AND is_published = 1').get(bookId);

    if (!book) {
        return res.status(404).render('404', { title: 'Book Not Found' });
    }

    if (!book.is_free && !req.session.isAdmin) {
        return res.redirect('/');
    }

    if (!book.file_path) {
        return res.status(404).render('error', { title: 'File Not Found', message: 'This book file is not available.' });
    }

    // Increment download count
    db.prepare('UPDATE books SET download_count = download_count + 1 WHERE id = ?').run(bookId);

    const filePath = require('path').join(__dirname, '..', 'public', book.file_path);
    res.download(filePath, book.title + '.' + book.file_format);
});

module.exports = router;
