{"content": "const express = require('express');
const router = express.Router();
const rateLimit = require('express-rate-limit');

// API limiter
const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 10,
    message: { error: 'Too many requests, please try again later.' }
});

// Subscribe to newsletter
router.post('/subscribe', apiLimiter, (req, res) => {
    const db = require('../db/database');
    const { email } = req.body;

    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return res.status(400).json({ success: false, error: 'Please provide a valid email address.' });
    }

    try {
        const existing = db.prepare('SELECT * FROM subscribers WHERE email = ?').get(email);

        if (existing) {
            if (existing.is_active) {
                return res.status(400).json({ success: false, error: 'This email is already subscribed.' });
            } else {
                // Reactivate subscription
                db.prepare('UPDATE subscribers SET is_active = 1, unsubscribed_at = NULL WHERE email = ?').run(email);
                return res.json({ success: true, message: 'Welcome back! Your subscription has been reactivated.' });
            }
        }

        db.prepare('INSERT INTO subscribers (email) VALUES (?)').run(email);
        res.json({ success: true, message: 'Thank you for subscribing! You will receive updates about new publications and resources.' });
    } catch (err) {
        console.error('Subscribe error:', err);
        res.status(500).json({ success: false, error: 'Failed to subscribe. Please try again.' });
    }
});

// Submit contact form
router.post('/contact', apiLimiter, (req, res) => {
    const db = require('../db/database');
    const { name, email, subject, message } = req.body;

    // Validation
    if (!name || name.trim().length < 2) {
        return res.status(400).json({ success: false, error: 'Please provide your name.' });
    }

    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return res.status(400).json({ success: false, error: 'Please provide a valid email address.' });
    }

    if (!message || message.trim().length < 10) {
        return res.status(400).json({ success: false, error: 'Please provide a message (at least 10 characters).' });
    }

    try {
        db.prepare('INSERT INTO contacts (name, email, subject, message) VALUES (?, ?, ?, ?)')
            .run(name.trim(), email.trim(), subject?.trim() || '', message.trim());

        res.json({ success: true, message: 'Thank you for your message! I will get back to you soon.' });
    } catch (err) {
        console.error('Contact error:', err);
        res.status(500).json({ success: false, error: 'Failed to send message. Please try again.' });
    }
});

// Unsubscribe
router.get('/unsubscribe', (req, res) => {
    const db = require('../db/database');
    const { email } = req.query;

    if (!email) {
        return res.redirect('/');
    }

    db.prepare('UPDATE subscribers SET is_active = 0, unsubscribed_at = CURRENT_TIMESTAMP WHERE email = ?').run(email);
    res.render('unsubscribed', { title: 'Unsubscribed' });
});

// Get published books (for potential API use)
router.get('/books', (req, res) => {
    const db = require('../db/database');

    const books = db.prepare(`
        SELECT id, title, description, author, cover_image, file_format, price, is_free 
        FROM books 
        WHERE is_published = 1 
        ORDER BY created_at DESC
    `).all();

    res.json(books);
});

module.exports = router;
